package com.jarvis.phone;
import android.content.*;import android.security.keystore.*;import android.util.Base64;import java.nio.charset.StandardCharsets;import java.security.KeyStore;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;
public final class LocalVault {private static final String STORE="jarvis_private",ALIAS="jarvis_v1_local_key";private final SharedPreferences prefs;public LocalVault(Context c){prefs=c.getSharedPreferences(STORE,Context.MODE_PRIVATE);}private SecretKey key()throws Exception{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);if(ks.containsAlias(ALIAS))return((KeyStore.SecretKeyEntry)ks.getEntry(ALIAS,null)).getSecretKey();KeyGenerator kg=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");kg.init(new KeyGenParameterSpec.Builder(ALIAS,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());return kg.generateKey();}public void put(String n,String v){try{Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key());byte[]e=c.doFinal(v.getBytes(StandardCharsets.UTF_8));prefs.edit().putString(n,Base64.encodeToString(c.getIV(),Base64.NO_WRAP)+"."+Base64.encodeToString(e,Base64.NO_WRAP)).apply();}catch(Exception ignored){}}public String get(String n,String d){String b=prefs.getString(n,null);if(b==null)return d;try{String[]p=b.split("\\.",2);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Base64.decode(p[0],Base64.NO_WRAP)));return new String(c.doFinal(Base64.decode(p[1],Base64.NO_WRAP)),StandardCharsets.UTF_8);}catch(Exception e){return d;}}public void clear(){prefs.edit().clear().apply();}}
